 "prop:unionassociative": {
  "id": "prop:unionassociative",
  "kind": "Proposition",
  "number": 17,
  "page": "13-unions.html",
  "title": "union is associative",
  "statement": "For any sets <span class='m'><i>X</i></span>, <span class='m'><i>Y</i></span> and <span class='m'><i>Z</i></span>, <span class='m'>(<i>X</i> ∪ <i>Y</i>) ∪ <i>Z</i> = <i>X</i> ∪ (<i>Y</i> ∪ <i>Z</i>)</span>.",
  "proof": "",
  "figure": ""
 },
