  "kind": "Proposition",
  "number": 20,
  "page": "13-unions.html",
  "title": "union respects inclusion",
  "statement": "For any sets <span class='m'><i>X</i></span>, <span class='m'><i>Y</i></span> and <span class='m'><i>Z</i></span>, if <span class='m'><i>X</i> ⊂ <i>Y</i></span>, then <span class='m'><i>X</i> ∪ <i>Z</i> ⊂ <i>Y</i> ∪ <i>Z</i></span>.",
