  "statement": "<div class='pic'><svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48.4 46.4' role='img' class='figsvg'><defs><pattern id='distributivity1-hNE' width='1.3' height='1.3' patternUnits='userSpaceOnUse'><path d='M 0 1.3 L 1.3 0' stroke='currentColor' stroke-width='0.15'/></pattern><clipPath id='distributivity1-c0'><path d='M 1.1999999999999993 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z'/></clipPath><clipPath id='distributivity1-c1'><path d='M 17.200000000000003 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z'/><path d='M 9.2 30.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z'/></clipPath></defs><g clip-path='url(#distributivity1-c1)'><g clip-path='url(#distributivity1-c0)'><rect x='0' y='0' width='48.4' height='46.4' fill='url(#distributivity1-hNE)'/></g></g><path d='M 1.1999999999999993 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z' fill='none' stroke='currentColor' stroke-width='0.18'/><path d='M 17.200000000000003 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z' fill='none' stroke='currentColor' stroke-width='0.18'/><path d='M 9.2 30.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z' fill='none' stroke='currentColor' stroke-width='0.18'/><text x='6.2' y='8.2' font-size='2.35' text-anchor='middle' dominant-baseline='central' font-family='Georgia, \"Times New Roman\", serif' font-style='italic' fill='currentColor'>X</text><text x='42.2' y='8.2' font-size='2.35' text-anchor='middle' dominant-baseline='central' font-family='Georgia, \"Times New Roman\", serif' font-style='italic' fill='currentColor'>Y</text><text x='24.2' y='38.2' font-size='2.35' text-anchor='middle' dominant-baseline='central' font-family='Georgia, \"Times New Roman\", serif' font-style='italic' fill='currentColor'>Z</text></svg></div><div class='pic'><svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48.4 46.4' role='img' class='figsvg'><defs><pattern id='distributivity2-hNE' width='1.3' height='1.3' patternUnits='userSpaceOnUse'><path d='M 0 1.3 L 1.3 0' stroke='currentColor' stroke-width='0.15'/></pattern><pattern id='distributivity2-hNW' width='1.3' height='1.3' patternUnits='userSpaceOnUse'><path d='M 0 0 L 1.3 1.3' stroke='currentColor' stroke-width='0.15'/></pattern><clipPath id='distributivity2-c0'><path d='M 1.1999999999999993 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z'/></clipPath><clipPath id='distributivity2-c1'><path d='M 17.200000000000003 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z'/></clipPath><clipPath id='distributivity2-c2'><path d='M 1.1999999999999993 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z'/></clipPath><clipPath id='distributivity2-c3'><path d='M 9.2 30.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z'/></clipPath></defs><g clip-path='url(#distributivity2-c1)'><g clip-path='url(#distributivity2-c0)'><rect x='0' y='0' width='48.4' height='46.4' fill='url(#distributivity2-hNE)'/></g></g><g clip-path='url(#distributivity2-c3)'><g clip-path='url(#distributivity2-c2)'><rect x='0' y='0' width='48.4' height='46.4' fill='url(#distributivity2-hNW)'/></g></g><path d='M 1.1999999999999993 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z' fill='none' stroke='currentColor' stroke-width='0.18'/><path d='M 17.200000000000003 16.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z' fill='none' stroke='currentColor' stroke-width='0.18'/><path d='M 9.2 30.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z' fill='none' stroke='currentColor' stroke-width='0.18'/><text x='6.2' y='8.2' font-size='2.35' text-anchor='middle' dominant-baseline='central' font-family='Georgia, \"Times New Roman\", serif' font-style='italic' fill='currentColor'>X</text><text x='42.2' y='8.2' font-size='2.35' text-anchor='middle' dominant-baseline='central' font-family='Georgia, \"Times New Roman\", serif' font-style='italic' fill='currentColor'>Y</text><text x='24.2' y='38.2' font-size='2.35' text-anchor='middle' dominant-baseline='central' font-family='Georgia, \"Times New Roman\", serif' font-style='italic' fill='currentColor'>Z</text></svg></div>",
