 "prop:differencesubset": {
  "id": "prop:differencesubset",
  "kind": "Proposition",
  "number": 27,
  "page": "15-relative-complements.html",
  "title": "a relative complement is a subset",
  "statement": "For any sets <span class='m'><i>X</i></span> and <span class='m'><i>Y</i></span>, <span class='m'><i>X</i> ∖ <i>Y</i> ⊂ <i>X</i></span>.",
  "proof": "<p>If <span class='m'><i>x</i> ∈ <i>X</i> ∖ <i>Y</i></span> then <span class='m'><i>x</i> ∈ <i>X</i></span> and <span class='m'><i>x</i> ∉ <i>Y</i></span>.\n\tIn particular, <span class='m'><i>x</i> ∈ <i>X</i></span>.</p>",
  "figure": ""
 },
