  "statement": "<div class='pic'><svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 72.4 42.4' role='img' class='figsvg'><defs><pattern id='complement-hNE' width='1.3' height='1.3' patternUnits='userSpaceOnUse'><path d='M 0 1.3 L 1.3 0' stroke='currentColor' stroke-width='0.15'/></pattern><mask id='complement-m0' maskUnits='userSpaceOnUse' x='0' y='0' width='72.4' height='42.4'><rect x='0' y='0' width='72.4' height='42.4' fill='#fff'/><path d='M 21.200000000000003 21.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z' fill='#000'/></mask><clipPath id='complement-c1'><path d='M 1.2 1.2 h 70.0 v 40.0 h -70.0 Z'/></clipPath></defs><g clip-path='url(#complement-c1)'><g mask='url(#complement-m0)'><rect x='0' y='0' width='72.4' height='42.4' fill='url(#complement-hNE)'/></g></g><path d='M 1.2 1.2 h 70.0 v 40.0 h -70.0 Z' fill='none' stroke='currentColor' stroke-width='0.18'/><path d='M 21.200000000000003 21.2 a 15.0 15.0 0 1 0 30.0 0 a 15.0 15.0 0 1 0 -30.0 0 Z' fill='none' stroke='currentColor' stroke-width='0.18'/><text x='36.2' y='21.2' font-size='2.35' text-anchor='middle' dominant-baseline='central' font-family='Georgia, \"Times New Roman\", serif' font-style='italic' fill='currentColor'>X</text><text x='6.2' y='6.2' font-size='2.35' text-anchor='middle' dominant-baseline='central' font-family='Georgia, \"Times New Roman\", serif' font-style='italic' stroke='var(--fig-bg, #fff)' stroke-width='1.55' stroke-linejoin='round' paint-order='stroke' fill='currentColor'>U</text></svg></div>",
